14	    pub fn start(device: &Arc<wgpu::Device>) -> Self {
15	        device.push_error_scope(wgpu::ErrorFilter::Validation);
16	        device.push_error_scope(wgpu::ErrorFilter::OutOfMemory);
17	        device.push_error_scope(wgpu::ErrorFilter::Internal);
