400	/// Selects an adapter for testing, preferring software rendering if available.
401	///
402	/// Panics if no adapter was found.
403	#[cfg(native)]
404	pub fn select_testing_adapter(instance: &wgpu::Instance) -> wgpu::Adapter {
405	    let mut adapters = instance.enumerate_adapters(wgpu::Backends::all());
406	    assert!(!adapters.is_empty(), "No graphics adapter found!");
407	
408	    re_log::debug!("Found the following adapters:");
409	    for adapter in &adapters {
410	        re_log::debug!("* {}", crate::adapter_info_summary(&adapter.get_info()));
411	    }
412	
413	    // Adapters are already sorted by preferred backend by wgpu, but let's be explicit.
414	    adapters.sort_by_key(|a| match a.get_info().backend {
415	        wgpu::Backend::Metal => 0,
416	        wgpu::Backend::Vulkan => 1,
417	        wgpu::Backend::Dx12 => 2,
418	        wgpu::Backend::Gl => 4,
419	        wgpu::Backend::BrowserWebGpu => 6,
420	        wgpu::Backend::Empty => 7,
421	    });
422	
423	    // Prefer CPU adapters, otherwise if we can't, prefer discrete GPU over integrated GPU.
424	    adapters.sort_by_key(|a| match a.get_info().device_type {
425	        wgpu::DeviceType::Cpu => 0, // CPU is the best for our purposes!
426	        wgpu::DeviceType::DiscreteGpu => 1,
427	        wgpu::DeviceType::Other
428	        | wgpu::DeviceType::IntegratedGpu
429	        | wgpu::DeviceType::VirtualGpu => 2,
430	    });
431	
432	    let adapter = adapters.remove(0);
433	    re_log::info!("Picked adapter: {:?}", adapter.get_info());
434	
435	    adapter
436	}
