3	/// Tries downcasting a given value into the specified possibilities (or all of them
4	/// if none are specified), then run the given expression on the downcasted value.
5	///
6	/// E.g. to `dbg!()` the downcasted value on a wgpu error:
7	/// ```ignore
8	/// try_downcast!(my_error => |inner| { dbg!(inner); })
9	/// ```
10	macro_rules! try_downcast {
11	    ($value:expr => |$binding:pat_param| $do:expr => [$ty:ty, $($tail:ty $(,)*),*]) => {
12	        try_downcast!($value => |$binding| $do => $ty);
13	        try_downcast!($value => |$binding| $do => [$($tail),*]);
14	    };
15	    ($value:expr => |$binding:pat_param| $do:expr => [$ty:ty $(,)*]) => {
16	        try_downcast!($value => |$binding| $do => $ty);
17	    };
18	    ($value:expr => |$binding:pat_param| $do:expr => $ty:ty) => {
19	        if let Some($binding) = ($value).downcast_ref::<$ty>() {
20	            break Some({ $do });
21	        }
22	    };
23	    ($value:expr => |$binding:pat_param| $do:expr) => {
24	        loop {
25	            try_downcast![$value => |$binding| $do => [
26	                wgpu_core::command::ClearError,
